"""Repository of the "audit_log" table: reads and writes rows, and decides nothing."""

from __future__ import annotations

from typing import Any, Protocol

from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession

from app.audit_log.entity import AuditLog


class AuditLogRepository(Protocol):
    """Where audit_log rows are kept. Services depend only on this interface."""

    async def list(self) -> list[AuditLog]:
        """Every row, by primary key."""
        ...


class SqlAuditLogRepository:
    """Keeps audit_log rows in the database, through a AsyncSession. It never commits: the transaction belongs to whoever holds the session."""

    def __init__(self, session: AsyncSession) -> None:
        self._session = session

    async def list(self) -> list[AuditLog]:
        """Every row, by primary key."""
        query = select(AuditLog)
        return list((await self._session.scalars(query.order_by(AuditLog.at, AuditLog.message))).all())


class MemoryAuditLogRepository:
    """Keeps audit_log rows in memory, for tests and for trying the services without a database."""

    def __init__(self) -> None:
        self._rows: dict[tuple[Any, ...], AuditLog] = {}

    @staticmethod
    def _key(row: AuditLog) -> tuple[Any, ...]:
        return (row.at, row.message,)

    async def list(self) -> list[AuditLog]:
        """Every row, by primary key."""
        return [row for row in sorted(self._rows.values(), key=self._key) if True]

