"""Operations on products: what each one checks before it writes."""

from collections.abc import Mapping
from datetime import UTC, datetime
from typing import Any

from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.product.entity import Product
from app.product_tag.entity import ProductTag
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"category_id", "name", "price", "status", "version", "deleted_at"})


class ProductService:
    """Operations on products. It never commits: the caller owns the transaction."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    async def _validate_all(self, values: dict[str, Any], current: Product | None) -> None:
        """Checks the values against the rules of the "products" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Product"))
        if not creating:
            for name in values.keys() & {"id", "version", "deleted_at"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("category_id")
        if value is None:
            if creating or "category_id" in values:
                errors.append(FieldError("category_id", "is required"))
        value = values.get("name")
        if value is None:
            if creating or "name" in values:
                errors.append(FieldError("name", "is required"))
        else:
            if isinstance(value, str) and len(value) > 100:
                errors.append(FieldError("name", "is longer than 100 characters"))
        value = values.get("price")
        if value is None:
            if creating or "price" in values:
                errors.append(FieldError("price", "is required"))
        else:
            if not value >= 0:
                errors.append(FieldError("price", "must be >= 0"))
        value = values.get("status")
        if value is None:
            if creating or "status" in values:
                errors.append(FieldError("status", "is required"))
        else:
            if isinstance(value, str) and len(value) > 10:
                errors.append(FieldError("status", "is longer than 10 characters"))
        value = values.get("version")
        if value is None:
            if "version" in values and not creating:
                errors.append(FieldError("version", "cannot be empty"))
        category_id = values["category_id"] if "category_id" in values else (getattr(current, "category_id") if current is not None else None)
        if category_id is not None and await self._uow.categories.find_by_id(category_id) is None:
            errors.append(FieldError("category_id", "no Category has this key"))
        if errors:
            raise ValidationFailedError("Product", errors)

    async def _check(self, values: dict[str, Any], current: Product | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        await self._validate_all(values, current)

    async def _find(self, id: int) -> Product:
        """The Product with this key; NotFoundError when there is none."""
        entity = await self._uow.products.find_by_id(id)
        if entity is None:
            raise NotFoundError("Product", id)
        return entity

    async def create_product(self, product: Product) -> Product:
        """Stores a new Product after checking it."""
        values = {name: getattr(product, name) for name in _FIELDS}
        await self._check(values, None)
        created = await self._uow.products.insert(product)
        return created

    async def get_product(self, id: int) -> Product:
        """The Product with this key; NotFoundError when there is none."""
        return await self._find(id)

    async def list_products(self) -> list[Product]:
        """Every Product, by primary key."""
        return await self._uow.products.list()

    async def update_product(self, id: int, changes: Mapping[str, Any], version: int) -> Product:
        """Changes the given values of a Product, read at `version`."""
        values = dict(changes)
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Product", "was changed by someone else since it was read", ("version",))
        await self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        current.version = version + 1
        updated = await self._uow.products.update(current)
        return updated

    async def delete_product(self, id: int, version: int) -> None:
        """Marks a Product as deleted (deleted_at); reads leave it out from then on."""
        current = await self._find(id)
        if current.version != version:
            raise ConflictError("Product", "was changed by someone else since it was read", ("version",))
        if await self._uow.order_lines.list_by_product_id(current.id):
            raise ConflictError("Product", "rows of order_lines still point to it", ("order_lines",))
        current.deleted_at = datetime.now(UTC)
        await self._uow.products.update(current)

    async def list_products_by_category_id(self, category_id: int) -> list[Product]:
        """The products with this category_id."""
        return await self._uow.products.list_by_category_id(category_id)

    async def add_tag(self, product_id: int, tag_id: int) -> None:
        """Links a Product and a Tag (product_tags)."""
        await self._find(product_id)
        if await self._uow.tags.find_by_id(tag_id) is None:
            raise NotFoundError("Tag", tag_id)
        if await self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id) is not None:
            raise ConflictError("Product", "is already linked to this Tag", ("tag_id",))
        await self._uow.product_tags.insert(ProductTag(product_id=product_id, tag_id=tag_id))

    async def remove_tag(self, product_id: int, tag_id: int) -> None:
        """Removes the link between a Product and a Tag (product_tags)."""
        link = await self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id)
        if link is None:
            raise NotFoundError("ProductTag", (product_id, tag_id))
        await self._uow.product_tags.delete(link)

