"""Rows for the tests: valid values for every column, and the rows they point to."""

from decimal import Decimal
from typing import Any

from app.category.entity import Category
from app.customer.entity import Customer
from app.order.entity import Order
from app.order_line.entity import OrderLine
from app.product.entity import Product
from app.product_tag.entity import ProductTag
from app.tag.entity import Tag
from app.unit_of_work import UnitOfWork


def new_customer(n: int = 1, **values: Any) -> Customer:
    """A valid Customer that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"email": f"email-{n}", "password_hash": f"passwordhash-{n}"}
    return Customer(**(defaults | values))


async def add_customer(uow: UnitOfWork, n: int = 1) -> Customer:
    """A stored Customer."""
    return await uow.customers.insert(new_customer(n))


def new_category(n: int = 1, **values: Any) -> Category:
    """A valid Category that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"name": f"name-{n}"}
    return Category(**(defaults | values))


async def add_category(uow: UnitOfWork, n: int = 1) -> Category:
    """A stored Category."""
    return await uow.categories.insert(new_category(n))


def new_product(n: int = 1, **values: Any) -> Product:
    """A valid Product that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"name": f"name-{n}", "price": Decimal(f"{n % 10000}.50"), "status": f"status-{n}", "version": n, "deleted_at": None}
    return Product(**(defaults | values))


async def add_product(uow: UnitOfWork, n: int = 1) -> Product:
    """A stored Product, with the rows it points to."""
    parent_0 = await add_category(uow, n)
    return await uow.products.insert(new_product(n, category_id=parent_0.id))


def new_order(n: int = 1, **values: Any) -> Order:
    """A valid Order that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {}
    return Order(**(defaults | values))


async def add_order(uow: UnitOfWork, n: int = 1) -> Order:
    """A stored Order, with the rows it points to."""
    parent_0 = await add_customer(uow, n)
    return await uow.orders.insert(new_order(n, customer_id=parent_0.id))


def new_order_line(n: int = 1, **values: Any) -> OrderLine:
    """A valid OrderLine that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"line": n, "quantity": n}
    return OrderLine(**(defaults | values))


async def add_order_line(uow: UnitOfWork, n: int = 1) -> OrderLine:
    """A stored OrderLine, with the rows it points to."""
    parent_0 = await add_order(uow, n)
    parent_1 = await add_product(uow, n)
    return await uow.order_lines.insert(new_order_line(n, order_id=parent_0.id, product_id=parent_1.id))


def new_tag(n: int = 1, **values: Any) -> Tag:
    """A valid Tag that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"label": f"label-{n}"}
    return Tag(**(defaults | values))


async def add_tag(uow: UnitOfWork, n: int = 1) -> Tag:
    """A stored Tag."""
    return await uow.tags.insert(new_tag(n))


def new_product_tag(n: int = 1, **values: Any) -> ProductTag:
    """A valid ProductTag that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {}
    return ProductTag(**(defaults | values))


async def add_product_tag(uow: UnitOfWork, n: int = 1) -> ProductTag:
    """A stored ProductTag, with the rows it points to."""
    parent_0 = await add_product(uow, n)
    parent_1 = await add_tag(uow, n)
    return await uow.product_tags.insert(new_product_tag(n, product_id=parent_0.id, tag_id=parent_1.id))
